insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('activity-media','activity-media',false,5242880,array['image/webp','image/jpeg','image/png','image/heic','image/heif']) on conflict(id) do update set public=false,file_size_limit=5242880;
drop policy if exists activity_media_select on storage.objects;create policy activity_media_select on storage.objects for select to authenticated using(bucket_id='activity-media' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists activity_media_insert on storage.objects;create policy activity_media_insert on storage.objects for insert to authenticated with check(bucket_id='activity-media' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists activity_media_update on storage.objects;create policy activity_media_update on storage.objects for update to authenticated using(bucket_id='activity-media' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='activity-media' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists activity_media_delete on storage.objects;create policy activity_media_delete on storage.objects for delete to authenticated using(bucket_id='activity-media' and (storage.foldername(name))[1]=auth.uid()::text);
